{
  "runId": "replay-jobs-1",
  "summary": "Complete the applyJob helper to be idempotent, record state for retries, and add tests for first apply, duplicate apply, and failure/resume.",
  "allowedFiles": [
    "src/jobs/jobs.js",
    "src/jobs/jobs.test.js"
  ],
  "operations": [
    {
      "type": "update_file",
      "path": "src/jobs/jobs.js",
      "content": "// src/jobs/jobs.js
// Half-built: only first success path sketched.
export const store = { applied: {}, pending: {} };

/**
 * Apply a job by id.
 * - Idempotent: calling with the same id again does nothing.
 * - Partial failure: if work throws, the id is recorded in pending so a retry can resume.
 * - Resume: after a failure the id stays in pending until a successful apply removes it.
 */
export function applyJob(id, work) {
  // If already applied, nothing to do.
  if (store.applied[id]) {
    return;
  }

  try {
    const result = work();
    // Record successful application.
    store.applied[id] = (store.applied[id] || 0) + 1;
    // Remove from pending if it was there.
    delete store.pending[id];
    return result;
  } catch (err) {
    // Record failure so a retry can resume later.
    store.pending[id] = true;
    // Ensure the id is not marked as applied.
    delete store.applied[id];
    throw err;
  }
}",
      "reason": "Implement full idempotent applyJob with pending state for retries."
    },
    {
      "type": "update_file",
      "path": "src/jobs/jobs.test.js",
      "content": "// src/jobs/jobs.test.js
import test from 'node:test';
import assert from 'node:assert/strict';
import { applyJob, store } from './jobs.js';

test('applies once', () => {
  Object.keys(store.applied).forEach((k) => delete store.applied[k]);
  Object.keys(store.pending).forEach((k) => delete store.pending[k]);
  assert.equal(applyJob('j1', () => 1), 1);
});

test('duplicate apply does nothing', () => {
  Object.keys(store.applied).forEach((k) => delete store.applied[k]);
  Object.keys(store.pending).forEach((k) => delete store.pending[k]);
  applyJob('j1', () => 1); // first apply
  const result = applyJob('j1', () => 2); // duplicate
  assert.strictEqual(result, undefined);
});

test('failure records pending and can resume', () => {
  Object.keys(store.applied).forEach((k) => delete store.applied[k]);
  Object.keys(store.pending).forEach((k) => delete store.pending[k]);
  // Simulate a failure
  assert.throws(() => applyJob('failId', () => {
    throw new Error('boom');
  }), Error('boom'));
  // Ensure pending is recorded
  assert.strictEqual(store.pending['failId'], true);
  // Resume after failure
  const resumeResult = applyJob('failId', () => 42);
  assert.strictEqual(resumeResult, 42);
  // Ensure it is now applied and pending cleared
  assert.strictEqual(store.applied['failId'], 1);
  assert.strictEqual(store.pending['failId'], undefined);
});

test('idempotent after successful resume', () => {
  Object.keys(store.applied).forEach((k) => delete store.applied[k]);
  Object.keys(store.pending).forEach((k) => delete store.pending[k]);
  applyJob('idempotent', () => 7);
  const second = applyJob('idempotent', () => 8);
  assert.strictEqual(second, undefined);
});

test('cannot apply after pending without resume', () => {
  Object.keys(store.applied).forEach((k) => delete store.applied[k]);
  Object.keys(store.pending).forEach((k) => delete store.pending[k]);
  // Failure leaves pending
  assert.throws(() => applyJob('stuck', () => {
    throw new Error('stuck');
  }), Error('stuck'));
  // Trying to apply again without a successful resume should still throw
  assert.throws(() => applyJob('stuck', () => 1), Error('stuck'));
});

test('store state is isolated per test', () => {
  // Clean up any leftover state
  Object.keys(store.applied).forEach((k) => delete store.applied[k]);
  Object.keys(store.pending).forEach((k) => delete store.pending[k]);
  // Simple sanity check that store starts empty
  assert.strictEqual(Object.keys(store.applied).length, 0);
  assert.strictEqual(Object.keys(store.pending).length, 0);
});"
      },
      "reason": "Add comprehensive tests covering first apply, duplicate apply, failure/resume, idempotency, and isolation."
    }
  ]
}
